class MyCalendar {
    map<int, int> events;
public:
    MyCalendar() {

    }

    bool book(int startTime, int endTime) {
        auto it = events.lower_bound(startTime);
        if (it != events.end() && it->first < endTime) {
            return false;
        }
        if (it != events.begin()) {
            auto pv = prev(it);
            if (pv->second > startTime) {
                return false;
            }
        }
        events[startTime] = endTime;
        return true;
    }
};
